<script>
(()=>{function init(){if(!window.jQuery||!window.jQuery.fn.DataTable){setTimeout(init,50);return;}const $=window.jQuery,base=@json(url('academic/medication-requests')),csrf=document.querySelector('meta[name="csrf-token"]').content;$('.select2').select2({theme:'bootstrap-5',width:'100%',dir:document.documentElement.dir==='rtl'?'rtl':'ltr'});$('.js-flatpickr-date').each(function(){if(window.flatpickr&&!this._flatpickr)flatpickr(this,{dateFormat:'Y-m-d',allowInput:true,disableMobile:true});});const table=$('#medicationTable').DataTable({processing:true,serverSide:true,ajax:{url:@json(route('academic.medication-requests.data')),data:d=>{d.parent_id=$('#filter_parent').val();d.student_id=$('#filter_student').val();d.date=$('#filter_date').val();d.done=$('#filter_done').val();}},columns:[{data:'DT_RowIndex',orderable:false,searchable:false},{data:'date'},{data:'student_name'},{data:'parent_name'},{data:'medicine_name'},{data:'dosage_amount'},{data:'nurse_name'},{data:'done_badge',orderable:false},{data:'actions',orderable:false,searchable:false}]});$('#filter_parent,#filter_student,#filter_date,#filter_done').on('change',()=>table.ajax.reload());function alertBox(type,msg){$('#medicationAlert').html(`<div class="alert alert-${type} alert-dismissible fade show">${msg}<button class="btn-close" data-bs-dismiss="alert"></button></div>`);}function clearForm(mode){const form=$(`#${mode}MedicationForm`)[0];form.reset();$(`#${mode}MedicationForm select`).val('').trigger('change');$(`#${mode}_date`).val(new Date().toISOString().slice(0,10));$(`#${mode}_medication_id`).val('');}$('#offcanvasAddMedication').on('show.bs.offcanvas',()=>clearForm('add'));$(document).on('click','.edit-medication',function(){$.get(`${base}/${$(this).data('id')}`,r=>{const d=r.data;$('#edit_medication_id').val(d.id);$('#edit_parent_id').val(d.parent_id).trigger('change');$('#edit_student_id').val(d.student_id).trigger('change');$('#edit_medicine_name').val(d.medicine_name);$('#edit_dosage_amount').val(d.dosage_amount);$('#edit_dosage_time').val(d.dosage_time);$('#edit_date').val(d.date);$('#edit_nurse_id').val(d.nurse_id).trigger('change');$('#edit_nurse_note').val(d.nurse_note);$('#edit_done').val(d.done?1:0).trigger('change');bootstrap.Offcanvas.getOrCreateInstance(document.getElementById('offcanvasEditMedication')).show();});});$('#addMedicationForm,#editMedicationForm').on('submit',function(e){e.preventDefault();const form=$(this),mode=form.attr('id').startsWith('add')?'add':'edit',id=$(`#${mode}_medication_id`).val(),payload=form.serialize(),url=id?`${base}/${id}`:base;$.ajax({url,type:'POST',data:payload,headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'},success:r=>{bootstrap.Offcanvas.getInstance(document.getElementById(`offcanvas${mode==='add'?'Add':'Edit'}Medication`)).hide();table.ajax.reload(null,false);alertBox('success',r.message);},error:x=>alertBox('danger',x.responseJSON?.message||@json(__('An error occurred.')))})});$(document).on('click','.complete-medication',function(){const id=$(this).data('id');$.ajax({url:`${base}/${id}/done`,type:'PATCH',data:{nurse_note:window.prompt(@json(__('Nurse Note')),'')||''},headers:{'X-CSRF-TOKEN':csrf},success:r=>{table.ajax.reload(null,false);alertBox('success',r.message);}});});$(document).on('click','.delete-medication',function(){if(!confirm(@json(__('Delete this medication request?'))))return;$.ajax({url:`${base}/${$(this).data('id')}`,type:'DELETE',headers:{'X-CSRF-TOKEN':csrf},success:r=>{table.ajax.reload(null,false);alertBox('success',r.message);}});});}init();})();
</script>
